package com.example.crsf2mocklocation.parser

import android.util.Log
import com.example.crsf2mocklocation.model.GpsData
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.flow
import java.nio.ByteBuffer
import java.nio.ByteOrder

private const val TAG = "MavlinkParser"

/**
 * Stateful MAVLINK v1/v2 frame parser.
 *
 * Supports:
 *   - GPS_RAW_INT         (msg 24)
 *   - GLOBAL_POSITION_INT (msg 33)
 *
 * Feed raw byte chunks via [push]; it returns a list of decoded [GpsData] fixes.
 * Use [parse] to get a Flow adapter over a byte-flow.
 */
object MavlinkParser {

    private const val MAVLINK_V1_STX   = 0xFE
    private const val MAVLINK_V2_STX   = 0xFD
    private const val MSG_GPS_RAW_INT  = 24
    private const val MSG_GLOBAL_POS   = 33

    private enum class State {
        IDLE,
        V1_LEN, V1_SEQ, V1_SYS, V1_COMP, V1_MSGID, V1_PAYLOAD, V1_CRC1, V1_CRC2,
        V2_LEN, V2_INCOMPAT, V2_COMPAT, V2_SEQ, V2_SYS, V2_COMP,
        V2_MSGID0, V2_MSGID1, V2_MSGID2, V2_PAYLOAD, V2_CRC1, V2_CRC2
    }

    private var state      = State.IDLE
    private var payloadLen = 0
    private var msgId      = 0
    private var payloadIdx = 0
    private val payload    = ByteArray(280)

    /** Push raw bytes; returns any GPS fixes decoded from this chunk. */
    fun push(bytes: ByteArray, len: Int = bytes.size): List<GpsData> {
        val results = mutableListOf<GpsData>()
        for (i in 0 until len) {
            val b = bytes[i].toInt() and 0xFF
            state = when (state) {
                State.IDLE -> when (b) {
                    MAVLINK_V1_STX -> State.V1_LEN
                    MAVLINK_V2_STX -> State.V2_LEN
                    else           -> State.IDLE
                }
                // -- V1 --
                State.V1_LEN    -> { payloadLen = b; State.V1_SEQ }
                State.V1_SEQ    -> State.V1_SYS
                State.V1_SYS    -> State.V1_COMP
                State.V1_COMP   -> State.V1_MSGID
                State.V1_MSGID  -> { msgId = b; payloadIdx = 0; if (payloadLen > 0) State.V1_PAYLOAD else State.V1_CRC1 }
                State.V1_PAYLOAD -> {
                    payload[payloadIdx++] = b.toByte()
                    if (payloadIdx >= payloadLen) State.V1_CRC1 else State.V1_PAYLOAD
                }
                State.V1_CRC1   -> State.V1_CRC2
                State.V1_CRC2   -> { decode(msgId, payloadLen)?.let { results += it }; State.IDLE }
                // -- V2 --
                State.V2_LEN      -> { payloadLen = b; State.V2_INCOMPAT }
                State.V2_INCOMPAT -> State.V2_COMPAT
                State.V2_COMPAT   -> State.V2_SEQ
                State.V2_SEQ      -> State.V2_SYS
                State.V2_SYS      -> State.V2_COMP
                State.V2_COMP     -> State.V2_MSGID0
                State.V2_MSGID0   -> { msgId = b; State.V2_MSGID1 }
                State.V2_MSGID1   -> { msgId = msgId or (b shl 8); State.V2_MSGID2 }
                State.V2_MSGID2   -> { msgId = msgId or (b shl 16); payloadIdx = 0; if (payloadLen > 0) State.V2_PAYLOAD else State.V2_CRC1 }
                State.V2_PAYLOAD  -> {
                    payload[payloadIdx++] = b.toByte()
                    if (payloadIdx >= payloadLen) State.V2_CRC1 else State.V2_PAYLOAD
                }
                State.V2_CRC1     -> State.V2_CRC2
                State.V2_CRC2     -> { decode(msgId, payloadLen)?.let { results += it }; State.IDLE }
            }
        }
        return results
    }

    /** Reset parser state — call on every new connection. */
    fun reset() {
        state = State.IDLE
        frameCount = 0
        seenMsgIds.clear()
        Log.d(TAG, "Parser reset")
    }

    // ---- Decoders ----

    // Track unique message IDs seen (for debug summary)
    private val seenMsgIds = mutableSetOf<Int>()
    private var frameCount = 0

    private fun decode(id: Int, len: Int): GpsData? {
        frameCount++
        seenMsgIds.add(id)
        // Log every frame at VERBOSE, and a summary every 50 frames
        Log.v(TAG, "Frame #$frameCount  v${if (id > 255) 2 else 1}  msgId=$id  payloadLen=$len")
        if (frameCount % 50 == 0) {
            Log.d(TAG, "--- $frameCount frames seen, unique msgIds: $seenMsgIds ---")
        }
        return when (id) {
            MSG_GPS_RAW_INT -> decodeGpsRawInt(len)
            MSG_GLOBAL_POS  -> decodeGlobalPositionInt(len)
            else            -> null
        }
    }

    /**
     * GPS_RAW_INT (msg 24) — little-endian wire order:
     * [0-7]  time_usec uint64
     * [8-11] lat  int32 degE7
     * [12-15] lon int32 degE7
     * [16-19] alt int32 mm MSL
     * [20-21] eph uint16 cm
     * [22-23] epv uint16
     * [24-25] vel uint16 cm/s
     * [26-27] cog uint16 cdeg
     * [28]   fix_type uint8
     * [29]   sats     uint8
     * MAVLINKv2 may truncate trailing zeros — minimum useful payload is 20 bytes (lat/lon/alt).
     */
    private fun decodeGpsRawInt(len: Int): GpsData? {
        if (len < 20) {
            Log.w(TAG, "GPS_RAW_INT too short: $len bytes")
            return null
        }
        val buf = ByteBuffer.wrap(payload, 0, len).order(ByteOrder.LITTLE_ENDIAN)
        buf.position(8)
        val lat = buf.int
        val lon = buf.int
        val alt = buf.int
        val eph = if (len >= 22) buf.short.toInt() and 0xFFFF else 100
        if (len >= 24) buf.short  // epv
        val vel = if (len >= 26) buf.short.toInt() and 0xFFFF else 0
        val cog = if (len >= 28) buf.short.toInt() and 0xFFFF else 0
        Log.d(TAG, "GPS_RAW_INT: lat=${lat/1e7} lon=${lon/1e7} alt=${alt/1000.0}m len=$len")
        return GpsData(
            latitude  = lat / 1e7,
            longitude = lon / 1e7,
            altitude  = alt / 1000.0,
            speed     = vel / 100f,
            bearing   = cog / 100f,
            hdop      = eph / 100f
        )
    }

    /**
     * GLOBAL_POSITION_INT (msg 33):
     * [0-3]  time_boot_ms uint32
     * [4-7]  lat          int32 degE7
     * [8-11] lon          int32 degE7
     * [12-15] alt         int32 mm MSL
     * [16-19] relative_alt int32 mm
     * [20-21] vx int16 cm/s
     * [22-23] vy int16 cm/s
     * [24-25] vz int16 cm/s
     * [26-27] hdg uint16 cdeg
     * MAVLINKv2 may truncate trailing zeros — minimum useful payload is 16 bytes (lat/lon/alt).
     */
    private fun decodeGlobalPositionInt(len: Int): GpsData? {
        if (len < 16) return null
        val buf = ByteBuffer.wrap(payload, 0, len).order(ByteOrder.LITTLE_ENDIAN)
        buf.position(4)
        val lat = buf.int
        val lon = buf.int
        val alt = buf.int
        if (len >= 20) buf.int  // relative_alt
        val vx  = if (len >= 22) buf.short.toInt() else 0
        val vy  = if (len >= 24) buf.short.toInt() else 0
        if (len >= 26) buf.short  // vz
        val hdg = if (len >= 28) buf.short.toInt() and 0xFFFF else 0
        val spd = Math.sqrt((vx / 100.0) * (vx / 100.0) + (vy / 100.0) * (vy / 100.0)).toFloat()
        return GpsData(
            latitude  = lat / 1e7,
            longitude = lon / 1e7,
            altitude  = alt / 1000.0,
            speed     = spd,
            bearing   = hdg / 100f
        )
    }

    /** Flow adapter — wraps a raw-bytes flow into a [GpsData] flow. */
    fun parse(byteFlow: Flow<ByteArray>): Flow<GpsData> = flow {
        reset()
        byteFlow.collect { chunk ->
            push(chunk).forEach { emit(it) }
        }
    }
}

